responseSchemaJson:
{
  "type": "object",
  "description": "知识记录大师的核心数据结构。旨在根据用户指令，提炼并结构化信息为多个可独立保存的知识条目。所有输出内容必须为简体中文(zh-CN)。",
  "properties": {
    "knowledgeRecording": {
      "type": "object",
      "description": "包含所有生成知识条目的模块。",
      "properties": {
        "entries": {
          "type": "array",
          "description": "根据用户指令生成的一个或多个独立知识条目的数组。",
          "items": {
            "type": "object",
            "description": "代表一个独立的知识条目。",
            "properties": {
              "name": {
                "type": "string",
                "description": "此知识条目的核心名称或标题。"
              },
              "category": {
                "type": "string",
                "description": "此知识条目所属的分类名称。"
              },
              "notes": {
                "type": "string",
                "description": "此知识条目的详细注释或核心内容文本。"
              }
            },
            "required": [
              "name",
              "category",
              "notes"
            ],
            "propertyOrdering": [
              "name",
              "category",
              "notes"
            ]
          }
        }
      },
      "required": [
        "entries"
      ],
      "propertyOrdering": [
        "entries"
      ]
    },
    "test": {
      "type": "object",
      "description": "[测试模块] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "knowledgeRecording",
    "test"
  ],
  "propertyOrdering": [
    "knowledgeRecording",
    "test"
  ]
}

responseSchemaParserJs:
try {
    const parts = responseJson?.candidates?.[0]?.content?.parts;
    if (!parts || !Array.isArray(parts) || parts.length === 0) {
        return { error: 'No content parts found in response' };
    }
    const potentialDataSource = parts[0];
    let rawText = '';
    if (typeof potentialDataSource === 'object' && potentialDataSource !== null && typeof potentialDataSource.text === 'string') {
        rawText = potentialDataSource.text;
    } else if (typeof potentialDataSource === 'string') {
        rawText = potentialDataSource;
    } else {
        return { error: 'Response data part is not a string or object with text.', rawData: potentialDataSource };
    }
    let jsonString = '';
    const firstBraceIndex = rawText.indexOf('{');
    const lastBraceIndex = rawText.lastIndexOf('}');
    if (firstBraceIndex !== -1 && lastBraceIndex !== -1 && lastBraceIndex > firstBraceIndex) {
        jsonString = rawText.substring(firstBraceIndex, lastBraceIndex + 1);
    } else {
        return { error: 'Could not find valid JSON braces {} in raw text.', rawText: rawText };
    }
    let data;
    try {
        data = JSON.parse(jsonString);
    } catch (e) {
        return { error: `Failed to parse extracted JSON: ${e.message}`, rawText: rawText, extractedJson: jsonString };
    }
    if (!data || typeof data !== 'object' || !data.knowledgeRecording || !Array.isArray(data.knowledgeRecording.entries)) {
        return { error: 'Parsed data is not a valid object or missing knowledgeRecording.entries module.' };
    }
    const entries = data.knowledgeRecording.entries;
    const actions = entries.map(e => ({
        type: 'description',
        content: `【知识条目: ${e.name}】\n分类: ${e.category}\n内容: ${e.notes}`
    }));

    return {
        processedTurnActions: actions,
        originalData: data
    };
} catch (e) {
    const rawResponseTextForError = responseJson?.candidates?.[0]?.content?.parts?.[0]?.text || "Raw text not available";
    return {
        error: `Parser exception: ${e.message}`,
        rawResponseForDebugging: rawResponseTextForError,
        stack: e.stack
    };
}
